  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: #D6202A;
  font-size: 10.5px;
  font-weight: 700;
  color: #fff;
}

.mc-sidebar__footer {
  margin-top: auto;
  padding: 10px 14px 16px;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mc-sidebar__logout {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 11px 14px;
  border: none;
  border-radius: 9px;
  background: none;
  color: rgba(255,255,255,0.85);
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 0.15s;
}

.mc-sidebar__logout:hover {
  background: rgba(255,255,255,0.12);
}

