/* Sidebar Mercantil (Custom Widget) — replica Sidebar.tsx/Sidebar.svelte:
 * ítems fijos de navegación, badge de contador en "Bandeja de tareas".
 * Single-page: dispara appsmith.triggerEvent('onNavigate', {tabName}) donde
 * tabName es el nombre lógico del tab del TABS_WIDGET raíz "mainScreen" — el
 * binding onNavigate del propio widget (definido en su JSON) hace
 * storeValue('selTab', tabName), NUNCA navigateTo() (que cambiaría de página
 * de la plataforma). Mismo patrón que navMenu.json en
 * backoffice-canales-personas (APAP), donde el menú custom solo dispara el
 * evento y quien decide qué hacer es el binding cableado en el widget padre. */

/* Solo los tabs que YA existen en tabsObj de mainScreen01 tienen tabName —
 * los módulos aún no construidos quedan con tabName: null (deshabilitados,
 * sin listener de clic) para no disparar storeValue('selTab', X) hacia un
 * tab que no existe (bug real: el TABS_WIDGET queda en un estado indefinido
 * si defaultTab no matchea ningún label de tabsObj). Se habilitan a medida
 * que se agregan sus tabs reales. */
const ITEMS = [
  { label: "Bandeja de tareas", tabName: "BandejaTareas", badgeKey: "pendingTaskCount" },
  { label: "Procesos", tabName: "Procesos" },
  { label: "Perfil del Cliente (piloto)", tabName: "PerfilCliente" },
  { label: "Casos", tabName: null },
  { label: "Monitorización", tabName: null }
];

/* Fija el tab inicial la primera vez que este widget se monta — reemplaza al
 * JSObject pageLoad + query executeOnLoad, que fallaba con "is not a
 * function" (el on-page-load real de Appsmith se calcula internamente por
 * análisis de dependencias, no es replicable con certeza en el JSON estático
 * exportado). Solo se fija si el store AÚN no tiene selTab, para no pisar
 * la navegación si el iframe del widget se remonta después de que el
 * usuario ya cambió de tab. */
appsmith.onReady(() => {
  if (!appsmith.store || !appsmith.store.selTab) {
    appsmith.triggerEvent("onNavigate", { tabName: "BandejaTareas" });
  }
  render(appsmith.model);
  if (typeof appsmith.onModelChange === "function") {
    appsmith.onModelChange((m) => render(m));
  }
});

function render(model) {
  const nav = document.getElementById("mc-nav");
  if (!nav) return;
  nav.innerHTML = "";

  const activeTab = model && model.activeTab;
  const pendingTaskCount = (model && model.pendingTaskCount) || 0;

  ITEMS.forEach((item) => {
    const disabled = !item.tabName;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "mc-nav-item" + (item.tabName === activeTab ? " active" : "") + (disabled ? " disabled" : "");
    if (disabled) btn.disabled = true;

    const label = document.createElement("span");
    label.className = "mc-nav-item__label";
    label.textContent = item.label;
    btn.appendChild(label);

    if (item.badgeKey && pendingTaskCount > 0) {
      const badge = document.createElement("span");
      badge.className = "mc-nav-item__badge";
      badge.textContent = String(pendingTaskCount);
      btn.appendChild(badge);
    }

    if (!disabled) {
      btn.addEventListener("click", () => {
        appsmith.triggerEvent("onNavigate", { tabName: item.tabName });
      });
    }

    nav.appendChild(btn);
  });
}

document.getElementById("mc-logout") && document.getElementById("mc-logout").addEventListener("click", () => {
  appsmith.triggerEvent("onLogout", {});
});

